/**
 * News is curated from the team's own sites. Pictures and write-ups stay
 * there, and every entry here links through to the fuller story.
 */

const anil = (slug: string) => `https://anil.recoil.org/notes/${slug}`;
const sam = (path: string) => `https://www.samreynolds.org/${path}`;

/** Responsive variants generated by anil.recoil.org for every image. */
const anilImg = (name: string, alt: string) => ({
  src: `https://anil.recoil.org/images/${name}.640.webp`,
  srcset: [320, 640, 1024]
    .map((w) => `https://anil.recoil.org/images/${name}.${w}.webp ${w}w`)
    .join(", "),
  alt
});

