/** Hostname an entry links through to, without the www prefix. */
export const linkHost = (url: string) =>
  new URL(url).hostname.replace(/^www\./, "");

const MONTHS = "Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec".split(" ");

/** "2026-01-08" -> "8 Jan 2026", without any Date/timezone involvement. */
export const formatDate = (iso: string) => {
  const [y, m, d] = iso.split("-").map(Number);
  return `${d} ${MONTHS[m - 1]} ${y}`;
};

/** Split into upcoming (soonest first) and past (newest first). */
export const splitEvents = (all: NewsEvent[], todayIso: string) => ({
  upcoming: all
    .filter((e) => e.date > todayIso)
    .sort((a, b) => a.date.localeCompare(b.date)),
  past: all
    .filter((e) => e.date <= todayIso)
    .sort((a, b) => b.date.localeCompare(a.date))
});
